<script setup lang="ts">
import {computed,onMounted,reactive,ref,watch} from 'vue';import P6Dialog from './P6Dialog.vue';import {amountCents,decimal,money} from './tradeAmounts';
type Row={id:string;[k:string]:any};type Request=<T>(path:string,method?:string,body?:unknown,headers?:Record<string,string>)=>Promise<T>;
const props=defineProps<{section:'targets'|'commissions'|'weeklies';request:Request;readonly:boolean;manager:boolean;canWrite:boolean;memberId:string}>();
const today=new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Shanghai'}).format(new Date());function monday(value:string){const d=new Date(value+'T00:00:00Z');d.setUTCDate(d.getUTCDate()-((d.getUTCDay()+6)%7));return d.toISOString().slice(0,10);}
const year=ref(Number(today.slice(0,4))),month=ref(today.slice(0,7)),week=ref(monday(today)),rows=ref<Row[]>([]),rules=ref<Row[]>([]),members=ref<Row[]>([]),departments=ref<Row[]>([]),busy=ref(false),error=ref(''),success=ref(''),dialog=ref(''),selected=ref<Row|null>(null),history=ref<Row[]>([]),key=ref('');
const form=reactive({scope:'member',memberId:'',departmentId:'',period:today.slice(0,7),months:1,amount:'',name:'',active:true,ruleId:'',progress:'',achievements:'',risks:'',nextActions:'',weekStart:monday(today),reason:''});
const tierRows=ref<{threshold:string;rate:string}[]>([{threshold:'0.00',rate:'3.00'}]);const editRule=ref<Row|null>(null);
const title=computed(()=>({targets:'业绩目标',commissions:'提成核算',weeklies:'销售周报'})[props.section]);const labels:Record<string,string>={DRAFT:'草稿',REVIEWED:'已复核',LOCKED:'已锁定',SUBMITTED:'待审批',APPROVED:'已批准',CREATED:'新建',UPDATED:'修改',CALCULATED:'试算',REVIEW:'复核',LOCK:'锁定',ADJUST:'追加调整',SUBMIT:'提交',APPROVE:'批准',REJECT:'退回'};
const manageable=computed(()=>props.manager&&props.canWrite&&!props.readonly);
async function run(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';success.value='';try{await fn();}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
async function options(){const r=await props.request<any>('/performance/options');members.value=r.members;departments.value=r.departments;const rs=await props.request<any>('/performance/rules');rules.value=rs.items;}
async function load(){let path=props.section==='targets'?`/performance/targets?year=${year.value}`:props.section==='commissions'?`/performance/commissions?period=${month.value}-01`:`/performance/weeklies?weekStart=${week.value}`;const r=await props.request<any>(path);rows.value=r.items;}
function create(){run(async()=>{await options();selected.value=null;key.value=crypto.randomUUID();Object.assign(form,{scope:'member',memberId:members.value[0]?.id??'',departmentId:departments.value[0]?.id??'',period:month.value,months:1,amount:'',ruleId:rules.value.find(x=>x.active)?.id??'',progress:'',achievements:'',risks:'',nextActions:'',weekStart:week.value,reason:''});dialog.value='create';});}
function edit(row:Row){run(async()=>{await options();selected.value=row;key.value=crypto.randomUUID();if(props.section==='targets')Object.assign(form,{scope:row.memberId?'member':'department',memberId:row.memberId??'',departmentId:row.departmentId??'',period:row.periodStart.slice(0,7),months:row.periodMonths,amount:decimal(row.targetCents)});else Object.assign(form,{weekStart:row.weekStart,progress:row.progress,achievements:row.achievements,risks:row.risks,nextActions:row.nextActions});dialog.value='create';});}
function save(){run(async()=>{let payload:any,path='',method='POST';if(props.section==='targets'){path='/performance/targets'+(selected.value?'/'+selected.value.id:'');method=selected.value?'PUT':'POST';payload={memberId:form.scope==='member'?form.memberId:null,departmentId:form.scope==='department'?form.departmentId:null,periodStart:Number(form.months)===12?form.period.slice(0,4)+'-01-01':form.period+'-01',periodMonths:Number(form.months),targetCents:amountCents(form.amount),expectedVersion:selected.value?.version??0};}else if(props.section==='commissions'){path='/performance/commissions/calculate';payload={memberId:form.memberId,ruleId:form.ruleId,periodStart:form.period+'-01',expectedVersion:rows.value.find(r=>r.memberId===form.memberId&&r.periodStart===form.period+'-01')?.version??0};}else{path='/performance/weeklies'+(selected.value?'/'+selected.value.id:'');method=selected.value?'PUT':'POST';payload={weekStart:form.weekStart,progress:form.progress,achievements:form.achievements,risks:form.risks,nextActions:form.nextActions,expectedVersion:selected.value?.version??0};}await props.request(path,method,payload,method==='POST'?{'Idempotency-Key':key.value}:{});dialog.value='';await load();success.value='已保存';});}
async function detail(row:Row){selected.value=row;const type=props.section==='targets'?'TARGET':props.section==='commissions'?'COMMISSION':'WEEKLY';const r=await props.request<any>(`/performance/history/${type}/${row.id}`);history.value=r.items;dialog.value='view';}
function view(row:Row){run(()=>detail(row));}
function action(act:string){form.reason='';form.amount='';key.value=crypto.randomUUID();dialog.value=act;}
function signed(value:string){if(!/^-?\d+(\.\d{1,2})?$/.test(value))throw new Error('调整金额最多两位小数');return (value.startsWith('-')?-1:1)*amountCents(value.replace('-',''));}
function apply(){run(async()=>{const old=selected.value!,act=dialog.value;const r=await props.request<Row>(`/performance/${props.section}/${old.id}/${act}`,'POST',{expectedVersion:old.version,reason:form.reason,deltaCents:act==='adjust'?signed(form.amount):null},{'Idempotency-Key':key.value});await load();await detail(r);success.value='操作已记录';});}
function showRules(){run(async()=>{await options();dialog.value='rules';});}
function ruleForm(r?:Row){editRule.value=r??null;form.name=r?.name??'';form.active=r?.active??true;tierRows.value=r?r.tiers.map((t:any)=>({threshold:decimal(t.thresholdCents),rate:(t.rateBps/100).toFixed(2)})):[{threshold:'0.00',rate:'3.00'}];key.value=crypto.randomUUID();dialog.value='rule-edit';}
function saveRule(){run(async()=>{const r=editRule.value;await props.request('/performance/rules'+(r?'/'+r.id:''),r?'PUT':'POST',{name:form.name,active:form.active,expectedVersion:r?.version??0,tiers:tierRows.value.map(t=>({thresholdCents:Number(t.threshold)===0?0:amountCents(t.threshold),rateBps:Math.round(Number(t.rate)*100)}))},r?{}:{'Idempotency-Key':key.value});await options();dialog.value='rules';success.value='规则已保存，历史核算快照保留';});}
function percent(row:Row){return (Number(row.actualCents)/Number(row.targetCents)*100).toFixed(1)+'%';}
watch(()=>props.section,()=>{dialog.value='';run(load);});onMounted(()=>run(load));
</script>
<template><section class="p6"><div class="page-heading"><div><span class="eyebrow">SALES PERFORMANCE</span><h1>{{title}}</h1><p>{{section==='targets'?'按年度与月度拆解部门、个人目标，按确认净到账跟踪完成率。':section==='commissions'?'按确认净到账分段计算，复核后锁定，调整保留独立记录。':'记录进展、成果、风险和下周行动，由主管审批归档。'}}</p></div><div class="p6-actions"><button v-if="section==='commissions'&&manageable" class="btn secondary" @click="showRules">提成规则</button><button v-if="section==='weeklies'?canWrite&&!readonly:manageable" class="btn primary" @click="create">{{section==='targets'?'设定目标':section==='commissions'?'提成试算':'填写周报'}}</button></div></div><div v-if="error&&!dialog" class="p6-error" role="alert">{{error}}</div><div v-if="success" class="p6-success" role="status">{{success}}</div><form class="p6-toolbar" @submit.prevent="run(load)"><label v-if="section==='targets'">年份<input v-model.number="year" type="number" min="2000" max="2100" required/></label><label v-else-if="section==='commissions'">核算月份<input v-model="month" type="month" required/></label><label v-else>周起始日（周一）<input v-model="week" type="date" required/></label><button class="btn secondary" :disabled="busy">查询 / 刷新</button></form><p v-if="section==='commissions'" class="p6-muted">采用超额累进阶梯：每一档仅计算该档区间。冲正按冲正日期计入净到账；本月可试算，月份结束后可锁定。试算人、复核人分离，不能复核本人提成。</p><div class="p6-card"><div class="table-scroll"><table><thead><tr><th>{{section==='targets'?'目标对象':'销售人员'}}</th><th>周期</th><th>{{section==='targets'?'目标 / 实际净到账':section==='commissions'?'净到账 / 提成':'状态 / 提交口径净到账'}}</th><th>{{section==='targets'?'完成率':section==='commissions'?'状态 / 调整额':'重点进展'}}</th><th>操作</th></tr></thead><tbody><tr v-for="r in rows" :key="r.id"><td>{{r.memberName||r.departmentName}}</td><td>{{r.periodStart||r.weekStart}}<small v-if="section==='targets'">{{r.periodMonths===12?'年度':'月度'}}</small></td><td v-if="section==='targets'">{{money(r.targetCents)}}<small>{{money(r.actualCents)}}</small></td><td v-else-if="section==='commissions'">{{money(r.baseCents)}}<small>提成 {{money(r.commissionCents)}}</small></td><td v-else>{{labels[r.status]}}<small>{{money(r.confirmedCents)}}</small></td><td v-if="section==='targets'">{{percent(r)}}<div class="p6-progress"><i :style="{width:Math.min(100,Math.max(0,Number(r.actualCents)/Number(r.targetCents)*100))+'%'}"/></div></td><td v-else-if="section==='commissions'">{{labels[r.status]}}<small>调整 {{money(r.adjustmentCents)}}</small></td><td v-else>{{r.progress.slice(0,40)}}</td><td><button class="text-button" @click="view(r)">详情</button><button v-if="section==='targets'&&manageable||section==='weeklies'&&r.status==='DRAFT'&&r.memberId===memberId&&canWrite&&!readonly" class="text-button" @click="edit(r)">编辑</button></td></tr><tr v-if="!rows.length"><td colspan="5">暂无记录</td></tr></tbody></table></div></div>
<P6Dialog v-if="dialog" :title="dialog==='rules'?'提成规则':dialog==='rule-edit'?'编辑提成规则':dialog==='view'?title+'详情':dialog==='create'?(selected?'编辑':'新增')+title:labels[dialog.toUpperCase()]||'处理记录'" :busy="busy" @close="!busy&&(dialog='')"><div v-if="error" class="p6-error" role="alert">{{error}}</div><template v-if="dialog==='view'&&selected"><h3>{{selected.memberName||selected.departmentName}} · {{selected.periodStart||selected.weekStart}}</h3><template v-if="section==='targets'"><p>目标 {{money(selected.targetCents)}} · 实际 {{money(selected.actualCents)}} · 完成 {{percent(selected)}}</p></template><template v-else-if="section==='commissions'"><div class="p6-kpis"><article><small>确认净到账</small><strong>{{money(selected.baseCents)}}</strong></article><article><small>原始提成</small><strong>{{money(selected.commissionCents)}}</strong></article><article><small>追加调整</small><strong>{{money(selected.adjustmentCents)}}</strong></article><article><small>合计</small><strong>{{money(Number(selected.commissionCents)+Number(selected.adjustmentCents))}}</strong></article></div><p>{{labels[selected.status]}} · 规则版本 {{selected.ruleVersion}}</p><div v-for="(t,i) in selected.ruleSnapshot" :key="i" class="p6-record">起点 {{money(t.thresholdCents)}} · 该档提成率 {{(t.rateBps/100).toFixed(2)}}%</div><div v-if="manageable" class="p6-actions"><button v-if="selected.status==='DRAFT'" class="btn primary" @click="action('review')">复核试算</button><button v-if="selected.status==='REVIEWED'" class="btn primary" @click="action('lock')">锁定核算</button><button v-if="selected.status==='LOCKED'" class="btn secondary" @click="action('adjust')">追加调整</button></div><div v-for="(a,i) in selected.adjustments" :key="i" class="p6-record">{{money(a.deltaCents)}} · {{a.reason}} · {{a.actorName}}</div></template><template v-else><p>{{labels[selected.status]}} · 提交时净到账 {{money(selected.confirmedCents)}}</p><h3>业务进展</h3><p class="p6-copy">{{selected.progress}}</p><h3>本周成果</h3><p class="p6-copy">{{selected.achievements||'未填'}}</p><h3>风险与协助</h3><p class="p6-copy">{{selected.risks||'未填'}}</p><h3>下一步行动</h3><p class="p6-copy">{{selected.nextActions}}</p><p class="p6-muted">审核说明：{{selected.reviewReason||'无'}}</p><div class="p6-actions"><button v-if="selected.status==='DRAFT'&&selected.memberId===memberId&&canWrite&&!readonly" class="btn primary" @click="action('submit')">提交主管</button><template v-if="selected.status==='SUBMITTED'&&manageable"><button class="btn primary" @click="action('approve')">批准归档</button><button class="btn secondary" @click="action('reject')">退回修改</button></template></div></template><h3>操作历史</h3><div v-for="h in history" :key="h.businessVersion" class="p6-record">v{{h.businessVersion}} · {{labels[h.action]||h.action}} · {{h.actorName}}<small class="p6-muted"> {{h.reason}} · {{h.createdAt}}</small></div></template>
<template v-else-if="dialog==='rules'"><button class="btn primary" @click="ruleForm()">新增规则</button><div v-for="r in rules" :key="r.id" class="p6-record"><strong>{{r.name}} · v{{r.version}} · {{r.active?'启用':'停用'}}</strong><p class="p6-muted">{{r.tiers.map((t:any)=>money(t.thresholdCents)+' 起 '+(t.rateBps/100)+'%').join('；')}}</p><button class="text-button" @click="ruleForm(r)">编辑 / 停用</button></div></template>
<form v-else-if="dialog==='rule-edit'" @submit.prevent="saveRule"><fieldset :disabled="busy||readonly"><label>规则名称<input v-model="form.name" maxlength="100" required/></label><div v-for="(r,i) in tierRows" :key="i" class="p6-grid"><label>第 {{i+1}} 档起点（元）<input v-model="r.threshold" inputmode="decimal" required/></label><label>提成比例（%）<input v-model="r.rate" type="number" min="0" max="100" step="0.01" required/></label></div><div class="p6-actions"><button type="button" class="btn secondary" :disabled="tierRows.length>=20" @click="tierRows.push({threshold:'',rate:''})">增加档位</button><button type="button" class="btn secondary" :disabled="tierRows.length<=1" @click="tierRows.pop()">移除末档</button></div><label><span><input v-model="form.active" type="checkbox" style="width:auto"/> 启用此规则</span></label></fieldset><button class="btn primary" :disabled="busy||readonly">保存规则</button></form>
<form v-else @submit.prevent="dialog==='create'?save():apply()"><fieldset :disabled="busy||readonly"><template v-if="dialog==='create'"><template v-if="section==='targets'"><div class="p6-grid"><label>目标范围<select v-model="form.scope" :disabled="!!selected"><option value="member">个人目标</option><option value="department">部门目标</option></select></label><label v-if="form.scope==='member'">人员<select v-model="form.memberId" required :disabled="!!selected"><option v-for="m in members" :key="m.id" :value="m.id">{{m.name}}</option></select></label><label v-else>部门<select v-model="form.departmentId" required :disabled="!!selected"><option v-for="d in departments" :key="d.id" :value="d.id">{{d.name}}</option></select></label><label>周期<select v-model="form.months" :disabled="!!selected"><option :value="1">月度</option><option :value="12">年度</option></select></label><label>月份 / 所属年度<input v-model="form.period" type="month" required :disabled="!!selected"/></label><label>目标金额（元）<input v-model="form.amount" inputmode="decimal" required/></label></div><p class="p6-muted">年度目标使用所选年份；已建年度目标时，月度拆分合计不能超过年度金额。</p></template><template v-else-if="section==='commissions'"><label>人员<select v-model="form.memberId" required><option v-for="m in members" :key="m.id" :value="m.id">{{m.name}}</option></select></label><label>核算月份<input v-model="form.period" type="month" required :max="today.slice(0,7)"/></label><label>提成规则<select v-model="form.ruleId" required><option value="">请选择</option><option v-for="r in rules.filter(x=>x.active)" :key="r.id" :value="r.id">{{r.name}} · v{{r.version}}</option></select></label><p class="p6-muted">已有未锁定核算会重新试算并退回草稿；已锁定核算不能覆盖。</p></template><template v-else><label>周起始日（周一）<input v-model="form.weekStart" type="date" required :disabled="!!selected" :max="today"/></label><label>业务进展<textarea v-model="form.progress" rows="4" maxlength="4000" required/></label><label>本周成果<textarea v-model="form.achievements" rows="3" maxlength="4000"/></label><label>风险与协助<textarea v-model="form.risks" rows="3" maxlength="4000"/></label><label>下一步行动<textarea v-model="form.nextActions" rows="4" maxlength="4000" required/></label></template></template><template v-else><p>{{selected?.memberName}} · {{selected?.periodStart||selected?.weekStart}}</p><label v-if="dialog==='adjust'">调整金额（元，扣减填负数）<input v-model="form.amount" inputmode="decimal" required/></label><label>说明<textarea v-model="form.reason" maxlength="500" rows="4" :required="['adjust','reject'].includes(dialog)"/></label></template></fieldset><button class="btn primary" :disabled="busy||readonly">{{busy?'处理中…':'确认保存'}}</button></form></P6Dialog></section></template>
